controls.NUMBER_PAIRS/a11y.beads.objectResponse:
{ $grabbedOrReleased ->
  [grabbed] { $side ->
              [left] grabbed, left of divider
              *[right] grabbed, right of divider
            }
  *[released] { $side ->
                [left] released, left of divider
                *[right] released, right of divider
              }
}

controls.NUMBER_PAIRS/a11y.gameScreen.countingAre:
{ $type ->
  [kittens] Right now, { $leftAddend } Yellow Kittens, { $rightAddend } Blue Kittens in Counting Area.
  *[numberLine] { $visible ->
                  [none] { a11y_gameScreen_countingArea_numberLineSentence }
                  [addends] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineAddends }
                  [tickMarks] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineTickMarks }
                  *[both] { a11y_gameScreen_countingArea_numberLineSentence } { a11y_gameScreen_countingArea_numberLineAddends } { a11y_gameScreen_countingArea_numberLineTickMarks }
                }
}

controls.NUMBER_PAIRS/a11y.gameScreen.responses.c:
{ $levelType ->
  [sum] You are correct! { $leftAddend } plus { $rightAddend } equals { $total }. { a11y_gameScreen_responses__correctAnswerScore }
  *[decomposition] You are correct! { $total } can be decomposed into { $leftAddend } and { $rightAddend }. { a11y_gameScreen_responses__correctAnswerScore }
}

controls.NUMBER_PAIRS/a11y.tenOrTwentyScreen.scre:
{ $representationType ->
  [beads] Navigate to and grab bead to create groups, or move across divider to change color.
  [kittens] Choose kitten to move, organize or change its color.
  [numberLine] Move addend splitter knob to change length of yellow and blue sections.
  *[location] { a11y_introScreen_screenSummary_interactionHint }
}
